import React, { useState } from "react";

function Login({ onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [role, setRole] = useState("user"); // Default: user
  const [error, setError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    setError("");

    if (role === "admin") {
      // ✅ Admin credentials fixed
      if (username === "admin" && password === "pass") {
        onLogin("admin", "admin_token");
      } else {
        setError("❌ Invalid admin credentials");
      }
    } else {
      // ✅ Any username/password allowed for user
      if (username.trim() && password.trim()) {
        onLogin("user", "user_token");
      } else {
        setError("⚠️ Please enter a username and password");
      }
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-4">
      <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-md">
        <h2 className="text-3xl font-bold text-center text-indigo-700 mb-6">
          {role === "admin" ? "Admin Login" : "User Login"}
        </h2>

        {/* Role Selector */}
        <div className="mb-4">
          <label className="block text-sm font-medium mb-1 text-gray-700">
            Login Type
          </label>
          <select
            value={role}
            onChange={(e) => setRole(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
        </div>

        {/* Error Message */}
        {error && (
          <div className="p-3 mb-4 rounded-lg text-sm bg-red-100 text-red-700 text-center">
            {error}
          </div>
        )}

        {/* Login Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Username
            </label>
            <input
              type="text"
              required
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Password
            </label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          <button
            type="submit"
            className="w-full mt-6 px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition duration-200"
          >
            Login
          </button>
        </form>

        {/* Info */}
        <p className="mt-6 text-center text-sm text-gray-500">
          {role === "admin"
            ? "Only admins know their credentials."
            : "Users can choose any username and password."}
        </p>
      </div>
    </div>
  );
}

export default Login;
